          <div id="status">készen</div>
        </div>
      </div>
      <div id="actions">
        <button class="iconbtn" id="clearBtn" type="button">Törlés</button>
        <button class="iconbtn" id="copyBtn" type="button">Másol</button>
      </div>
    </div>

    <div id="chatwrap">
      <div id="msgs" aria-live="polite"></div>

      <div id="composer">
        <div id="bar">
          <div id="lefttools">
            <div class="glyph" id="attachBtn" role="button" tabindex="0" aria-label="Csatolás">📎</div>
            <div class="glyph" id="sparkBtn" role="button" tabindex="0" aria-label="Műveletek">✦</div>
          </div>
          <textarea id="input" rows="1" placeholder="Írj ide..." autocomplete="off" autocapitalize="sentences" spellcheck="true"></textarea>
          <div id="send" role="button" tabindex="0" aria-disabled="true" aria-label="Küldés">↑</div>
        </div>

        <div id="toggles">
          <div class="pill" id="deepBtn">DeepSearch</div>
          <div class="pill" id="thinkBtn">Think</div>
          <div class="pill on" id="compactBtn">Compact</div>
          <div class="pill on" id="safeHistoryBtn">Safe history</div>
        </div>
      </div>

      <div id="overlay">
        <div id="searchpill">
          <div id="spinner"></div>
          <div class="label">
            <div class="h">DeepSearch</div>
            <div class="s" id="searchStatus">Keresés folyamatban...</div>
          </div>
          <button id="stop" type="button">Stop</button>
        </div>
      </div>
    </div>
  </div>

  <div id="toast"></div>
  <input id="file" type="file" />

  <script>
    (function(){
      const $=(id)=>document.getElementById(id);

      const msgs=$("msgs");
      const input=$("input");
      const send=$("send");
      const deepBtn=$("deepBtn");
      const thinkBtn=$("thinkBtn");
      const compactBtn=$("compactBtn");
      const safeHistoryBtn=$("safeHistoryBtn");
      const statusEl=$("status");
      const connDot=$("connDot");
      const searchpill=$("searchpill");
      const searchStatus=$("searchStatus");
      const stopBtn=$("stop");
      const clearBtn=$("clearBtn");
      const copyBtn=$("copyBtn");
      const attachBtn=$("attachBtn");
      const sparkBtn=$("sparkBtn");
      const fileInput=$("file");
      const toast=$("toast");

      let enableSearch=false;
      let showReasoning=false;
      let compactMode=true;
      let safeHistory=true;

      let isStreaming=false;
      let abortCtrl=null;

      const state={messages:[],currentAssistantMsgId:null,currentAssistantText:"",currentReasoningText:"",lastInfoText:"",searching:false};

      const SETTINGS_KEY="chat_ui_settings_v3";
      function loadSettings(){
        try{
          const raw=localStorage.getItem(SETTINGS_KEY);
          if(!raw) return;
          const obj=JSON.parse(raw);
          enableSearch=!!obj.enableSearch;
          showReasoning=!!obj.showReasoning;
          compactMode=obj.compactMode!==false;
          safeHistory=obj.safeHistory!==false;
        }catch(e){}
      }
      function saveSettings(){
        try{
          localStorage.setItem(SETTINGS_KEY, JSON.stringify({enableSearch,showReasoning,compactMode,safeHistory}));
        }catch(e){}
      }

      function setPill(el,on){ if(on) el.classList.add("on"); else el.classList.remove("on"); }
      function updateToggles(){ setPill(deepBtn,enableSearch); setPill(thinkBtn,showReasoning); setPill(compactBtn,compactMode); setPill(safeHistoryBtn,safeHistory); }

      function toastMsg(text){
        toast.style.display="block";
        toast.textContent=text;
        clearTimeout(toast._t);
        toast._t=setTimeout(()=>{ toast.style.display="none"; }, 1600);
      }

      function escapeHtml(s){
        return String(s).replace(/[&<>"']/g,(c)=>({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));
      }
      function linkify(text){
        const s=String(text);
        const re=/\\bhttps?:\\/\\/[^\\s<>()]+/gi;
        let out="",last=0,m;
        while((m=re.exec(s))!==null){
          const start=m.index,url=m[0];
          out+=escapeHtml(s.slice(last,start));
          out+=''+escapeHtml(url)+'';
          last=start+url.length;
        }
        out+=escapeHtml(s.slice(last));
        return out;
      }

      function scrollToBottom(soft){
        if(soft){
          const near=msgs.scrollHeight-msgs.scrollTop-msgs.clientHeight<180;
          if(!near) return;
        }
        msgs.scrollTop=msgs.scrollHeight;
      }

      function render(){
        msgs.innerHTML="";
        const frag=document.createDocumentFragment();
        for(const m of state.messages){
          const row=document.createElement("div");
          row.className="msg "+m.role;
          const av=document.createElement("div");
          av.className="avatar";
          av.textContent=m.role==="user"?"Te":"AI";
          const b=document.createElement("div");
          b.className="bubble";
          const body=document.createElement("div");
          body.innerHTML=linkify(m.content||"");
          b.appendChild(body);

          if(m.reasoning && showReasoning){
            const meta=document.createElement("div");
            meta.className="meta mono";
            meta.textContent="reasoning "+m.reasoning;
            b.appendChild(meta);
          }
          if(m.info){
            const meta2=document.createElement("div");
            meta2.className="meta";
            meta2.textContent="info "+m.info;
            b.appendChild(meta2);
          }

          row.appendChild(av);
          row.appendChild(b);
          frag.appendChild(row);
        }
        msgs.appendChild(frag);
        scrollToBottom(false);
      }

      function addUserMessage(text){
        state.messages.push({id:crypto.randomUUID(),role:"user",content:text});
        render();
      }

      function upsertAssistantMessage(partial){
        const id=state.currentAssistantMsgId||crypto.randomUUID();
        state.currentAssistantMsgId=id;
        let found=null;
        for(const m of state.messages){ if(m.id===id){ found=m; break; } }
        if(!found){ found={id,role:"assistant",content:""}; state.messages.push(found); }
        if(typeof partial.content==="string") found.content=partial.content;
        if(typeof partial.reasoning==="string") found.reasoning=partial.reasoning;
        if(typeof partial.info==="string") found.info=partial.info;
        render();
      }

      function setConnected(on){
        if(on){ connDot.classList.remove("off"); statusEl.textContent=isStreaming?"folyamatban...":"készen"; }
        else{ connDot.classList.add("off"); statusEl.textContent="offline"; }
      }

      function setSearching(on,sub){
        state.searching=on;
        if(on){ searchpill.style.display="flex"; searchStatus.textContent=sub||"Keresés folyamatban..."; }
        else{ searchpill.style.display="none"; searchStatus.textContent=""; }
      }

      function setStreaming(on){
        isStreaming=on;
        if(on){ send.setAttribute("aria-disabled","true"); statusEl.textContent="folyamatban..."; }
        else{ statusEl.textContent="készen"; send.setAttribute("aria-disabled", input.value.trim().length ? "false":"true"); }
      }

      function autoGrow(){
        input.style.height="0px";
        const h=Math.min(120,Math.max(32,input.scrollHeight));
        input.style.height=h+"px";
      }

      function canSend(){ return !isStreaming && input.value.trim().length>0; }
      function setSendEnabled(){ send.setAttribute("aria-disabled", canSend() ? "false":"true"); }

      function normalizeHistoryForBackend(){
        const out=[];
        const maxMsgs=safeHistory?10:40;
        const slice=state.messages.filter(m=>m.role==="user"||m.role==="assistant").slice(-maxMsgs);
        for(const m of slice){
          const content=(m.content||"").toString();
          if(!content.trim()) continue;
          out.push({role:m.role,content:content});
        }
        return out;
      }

      async function postChat(payload){
        const res=await fetch("/chat",{method:"POST",headers:{ "Content-Type":"application/json" },body:JSON.stringify(payload)});
        if(!res.ok){
          const t=await res.text().catch(()=> "");
          throw new Error("HTTP "+res.status+(t?" "+t:""));
        }
        return res;
      }

      function parseSse(buffer){
        const events=[];
        let idx;
        while((idx=buffer.indexOf("\\n\\n"))!==-1){
          const raw=buffer.slice(0,idx);
          buffer=buffer.slice(idx+2);
          const lines=raw.split("\\n");
          for(const line of lines){
            if(line.startsWith("data:")){
              const data=line.slice(5).trim();
              events.push(data);
            }
          }
        }
        return {events,buffer};
      }

      async function streamChat(userText){
        setConnected(true);
        setSearching(false);
        state.currentAssistantMsgId=null;
        state.currentAssistantText="";
        state.currentReasoningText="";
        state.lastInfoText="";
        upsertAssistantMessage({content:""});

        const history=normalizeHistoryForBackend();
        const payload={message:userText,enable_search:enableSearch,history:history};

        abortCtrl=new AbortController();
        setStreaming(true);

        let res;
        try{ res=await postChat(payload); }
        catch(err){
          setStreaming(false);
          setSearching(false);
          upsertAssistantMessage({info:"Hiba: "+String(err && err.message ? err.message : err)});
          toastMsg("Hálózati hiba");
          return;
        }

        const reader=res.body && res.body.getReader ? res.body.getReader() : null;
        if(!reader){
          setStreaming(false);
          upsertAssistantMessage({info:"A böngésző nem támogatja a streamet."});
          return;
        }

        let buf="";
        const dec=new TextDecoder("utf-8");
        try{
          while(true){
            const {value,done}=await reader.read();
            if(done) break;
            if(abortCtrl && abortCtrl.signal.aborted) break;
            buf+=dec.decode(value,{stream:true});
            const parsed=parseSse(buf);
            buf=parsed.buffer;
            for(const e of parsed.events){
              if(e==="[DONE]") throw new Error("__DONE__");
              let obj=null;
              try{ obj=JSON.parse(e); }catch(_){ obj=null; }
              if(!obj || typeof obj!=="object") continue;
              const type=obj.type;
              const content=(obj.content ?? "").toString();

              if(type==="content"){
                state.currentAssistantText+=content;
                upsertAssistantMessage({content:state.currentAssistantText});
                scrollToBottom(true);
              }else if(type==="reasoning"){
                state.currentReasoningText+=content;
