def _safe_json_dumps(obj: Any) -> str:
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"), default=str)

def _sse(obj: Dict[str, Any]) -> str:
    return "data: " + _safe_json_dumps(obj) + "\n\n"

def _now_ms() -> int:
    return int(time.time() * 1000)

def _client_ip() -> str:
    xf = request.headers.get("X-Forwarded-For", "")
    if xf:
        first = xf.split(",")[0].strip()
        if first:
            return first[:64]
    ra = request.environ.get("REMOTE_ADDR", "") or "unknown"
    return str(ra)[:64]

def _normalize_tag(s: str) -> str:
    s = (s or "").strip()
    if not s:
        return ""
    out = []
    for ch in s:
        o = ord(ch)
        if 48 <= o <= 57 or 65 <= o <= 90 or 97 <= o <= 122 or ch in ("-", "_"):
            out.append(ch.lower())
        else:
            out.append("-")
    t = "".join(out).strip("-")
    return t[:80] if t else ""

def _container_tag() -> str:
    base = _normalize_tag(SUPERMEMORY_TAG_PREFIX) or "app"
    ip = _normalize_tag(_client_ip())
    return f"{base}:{ip}" if ip else f"{base}:anon"

def _sanitize_user_text(s: Any, limit: int) -> str:
    if not isinstance(s, str):
        return ""
    s = s.replace("\u0000", "").strip()
    if len(s) > limit:
        s = s[:limit]
    return s

def _validate_date_yyyy_mm_dd(s: Any) -> Optional[str]:
    if not isinstance(s, str):
        return None
    s = s.strip()
    if not s:
        return None
    try:
        datetime.strptime(s, "%Y-%m-%d")
        return s
    except Exception:
        return None

def _sanitize_domains(v: Any) -> Optional[List[str]]:
    if not isinstance(v, list):
        return None
    out: List[str] = []
    for x in v:
        if not isinstance(x, str):
            continue
        d = x.strip().lower()
        if not d or "://" in d or "/" in d or " " in d:
            continue
        if len(d) > 253:
            continue
        out.append(d)
    if not out:
        return None
    seen = set()
    dedup = []
    for d in out:
        if d in seen:
            continue
        seen.add(d)
        dedup.append(d)
    return dedup[:200]

def _pick_cerebras_client() -> Cerebras:
    global _cerebras_idx
    with _cerebras_lock:
        c = _cerebras_clients[_cerebras_idx % len(_cerebras_clients)]
        _cerebras_idx = (_cerebras_idx + 1) % len(_cerebras_clients)
        return c

def _rotate_cerebras_client() -> Cerebras:
    global _cerebras_idx
    with _cerebras_lock:
        _cerebras_idx = (_cerebras_idx + 1) % len(_cerebras_clients)
        return _cerebras_clients[_cerebras_idx]

def _is_rate_limit_error(e: Exception) -> bool:
    sc = getattr(e, "status_code", None)
    if sc == 429:
        return True
    msg = str(e).lower()
    return ("429" in msg) or ("too many requests" in msg) or ("rate limit" in msg)

def _is_context_len_error(e: Exception) -> bool:
    sc = getattr(e, "status_code", None)
    msg = str(e).lower()
    if sc == 400 and ("context_length_exceeded" in msg or "reduce the length of the messages" in msg or "limit is" in msg):
        return True
    return "context_length_exceeded" in msg

def _cerebras_stream_create(params: Dict[str, Any], max_attempts: int = 10) -> Any:
    last_err: Optional[Exception] = None
    for attempt in range(max_attempts):
        client = _pick_cerebras_client() if attempt == 0 else _rotate_cerebras_client()
        try:
            return client.chat.completions.create(**params)
        except Exception as e:
            last_err = e
            if _is_rate_limit_error(e):
                sleep_s = min(12.0, (2 ** min(attempt, 4)) + random.random())
                logger.info(f"Cerebras 429, retry in {sleep_s:.2f}s")
                time.sleep(sleep_s)
                continue
            raise
    if last_err:
        raise last_err
    raise RuntimeError("Cerebras create failed")

def _messages_char_len(messages: List[Dict[str, Any]]) -> int:
    total = 0
    for m in messages:
        c = m.get("content")
        if isinstance(c, str):
            total += len(c)
        tc = m.get("tool_calls")
        if tc is not None:
            total += len(_safe_json_dumps(tc))
        if m.get("role") == "tool":
            total += len(m.get("content", "") or "")
    return total

def _prune_history(messages: List[Dict[str, Any]], keep_system: int, max_chars: int) -> List[Dict[str, Any]]:
    sys_msgs = [m for m in messages if m.get("role") == "system"][:keep_system]
    rest = [m for m in messages if m.get("role") != "system"]
    trimmed: List[Dict[str, Any]] = []
    cur = 0
    for m in reversed(rest):
        add = 0
        c = m.get("content")
        if isinstance(c, str):
            add += len(c)
        tc = m.get("tool_calls")
        if tc is not None:
            add += len(_safe_json_dumps(tc))
        if m.get("role") == "tool":
            add += len(m.get("content", "") or "")
        if cur + add > max_chars:
            continue
        trimmed.append(m)
        cur += add
    trimmed.reverse()
    return sys_msgs + trimmed

def _supermemory_headers() -> Dict[str, str]:
    return {"Authorization": f"Bearer {SUPERMEMORY_API_KEY}", "Content-Type": "application/json"}

def _supermemory_ok() -> bool:
    return bool(SUPERMEMORY_API_KEY)

def supermemory_add_document(text: str, tags: List[str], metadata: Optional[Dict[str, Any]]) -> bool:
    if not _supermemory_ok():
        return False
    t = _sanitize_user_text(text, 200000)
    if not t:
        return False
    tgs: List[str] = []
    for tg in tags:
        if isinstance(tg, str):
            s = tg.strip()
            if s:
                tgs.append(s[:160])
    if not tgs:
        tgs = [_container_tag()]
    body: Dict[str, Any] = {"text": t, "tags": tgs}
    if isinstance(metadata, dict) and metadata:
        body["metadata"] = metadata
    url = f"{SUPERMEMORY_BASE_URL}/v3/documents"
    r = requests.post(url, headers=_supermemory_headers(), data=_safe_json_dumps(body), timeout=SUPERMEMORY_ADD_TIMEOUT)
    if 200 <= r.status_code < 300:
        return True
    logger.error(f"Supermemory add failed: {r.status_code} {r.text[:800]}")
    return False

def supermemory_search(q: str, tags: List[str], limit: int) -> List[Dict[str, Any]]:
    if not _supermemory_ok():
        return []
    qq = _sanitize_user_text(q, 12000)
    if not qq:
        return []
    tgs: List[str] = []
    for tg in tags:
        if isinstance(tg, str):
            s = tg.strip()
            if s:
                tgs.append(s[:160])
    if not tgs:
        tgs = [_container_tag()]
    lim = int(limit)
    if lim < 1:
        lim = 1
    if lim > 200:
        lim = 200
    url = f"{SUPERMEMORY_BASE_URL}/v4/search"
    body = {"q": qq, "limit": lim, "tags": tgs}
    r = requests.post(url, headers=_supermemory_headers(), data=_safe_json_dumps(body), timeout=SUPERMEMORY_SEARCH_TIMEOUT)
    if not (200 <= r.status_code < 300):
        logger.error(f"Supermemory search failed: {r.status_code} {r.text[:800]}")
        return []
    try:
        data = r.json()
    except Exception:
        return []
    res = None
    if isinstance(data, dict):
        if isinstance(data.get("results"), list):
            res = data.get("results")
        elif isinstance(data.get("data"), dict) and isinstance(data["data"].get("results"), list):
            res = data["data"].get("results")
    if not isinstance(res, list):
        return []
    out: List[Dict[str, Any]] = []
    for item in res[:lim]:
        if not isinstance(item, dict):
            continue
        txt = item.get("text") or item.get("content") or item.get("chunk") or ""
        if not isinstance(txt, str):
            txt = str(txt)
        txt = txt.strip()
        if not txt:
            continue
        if len(txt) > 1200:
            txt = txt[:1200]
        out.append({"text": txt, "score": item.get("score"), "id": item.get("id")})
    return out

def _exa_item_get(item: Any, key: str, default: Any = "") -> Any:
    if isinstance(item, dict):
        return item.get(key, default)
    return getattr(item, key, default)

def _truncate(s: Any, n: int) -> str:
    if s is None:
        return ""
    if not isinstance(s, str):
        s = str(s)
    s = s.strip()
    return s if len(s) <= n else s[:n]

def _exa_search_one(query: str, search_type: str, use_filters: bool, include_domains: Optional[List[str]], exclude_domains: Optional[List[str]], start_published_date: Optional[str], end_published_date: Optional[str], category: Optional[str], include_text: Optional[List[str]], exclude_text: Optional[List[str]]) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    params: Dict[str, Any] = {
        "query": query,
        "num_results": EXA_NUM_RESULTS_PER_QUERY,
        "type": search_type,
        "text": True,
        "highlights": True
    }
    if use_filters:
        if include_domains:
            params["include_domains"] = include_domains
        if exclude_domains:
            params["exclude_domains"] = exclude_domains
        if start_published_date:
            params["start_published_date"] = start_published_date
        if end_published_date:
            params["end_published_date"] = end_published_date
        if category:
            params["category"] = category
        if include_text and isinstance(include_text, list) and include_text:
            it = include_text[0]
            if isinstance(it, str) and it.strip():
                params["include_text"] = [it.strip()[:120]]
        if exclude_text and isinstance(exclude_text, list) and exclude_text:
            et = exclude_text[0]
            if isinstance(et, str) and et.strip():
                params["exclude_text"] = [et.strip()[:120]]
    res = exa_client.search_and_contents(**params)
    results = getattr(res, "results", None)
    if not isinstance(results, list):
        results = []
    all_meta: List[Dict[str, Any]] = []
    top: List[Dict[str, Any]] = []
    seen_urls: set = set()
    for idx, item in enumerate(results):
        url = _truncate(_exa_item_get(item, "url", ""), 2000)
        if url and url in seen_urls:
            continue
        if url:
            seen_urls.add(url)
        title = _truncate(_exa_item_get(item, "title", ""), 300)
        published_date = _exa_item_get(item, "published_date", None)
        author = _exa_item_get(item, "author", None)
        all_meta.append({
            "title": title,
            "url": url,
            "published_date": _truncate(published_date, 80) if published_date is not None else None,
            "author": _truncate(author, 120) if author is not None else None
        })
        if idx < EXA_TOP_SNIPPETS_PER_QUERY:
            text = _truncate(_exa_item_get(item, "text", ""), EXA_TEXT_CHARS_PER_TOP)
            highlights = _exa_item_get(item, "highlights", [])
            hlist: List[str] = []
            if isinstance(highlights, list):
                for h in highlights[:EXA_HIGHLIGHTS_PER_TOP]:
                    if isinstance(h, str):
                        hh = h.strip()
                        if hh:
                            hlist.append(hh[:EXA_HIGHLIGHT_CHARS])
            top.append({"title": title, "url": url, "text": text, "highlights": hlist})
    return all_meta, top

